export function SectionHead({
  emoji,
  title,
  titleAr,
  sub,
  subAr,
  color = DS.cyan,
  action,
}: {
  emoji: React.ReactNode;
  title: string;
  titleAr?: string;
  sub?: string;
  subAr?: string;
  color?: string;
  action?: { label: string; labelAr?: string; onClick: () => void };
}) {
  const { language } = useLanguage();
  const ar = language === 'ar';
  const displayTitle = ar && titleAr ? titleAr : title;
  const displaySub = ar && subAr ? subAr : sub;
  const displayLabel = action && ar && action.labelAr ? action.labelAr : action?.label;

  return (
    <div
      className="sp-head"
      style={{
        background: DS.gradNav,
        borderRadius: r(20),
        padding: '24px 24px',
        marginBottom: 20,
        position: 'relative',
        overflow: 'hidden',
        border: `1px solid ${color}18`,
        boxShadow: '0 8px 32px rgba(8,29,57,0.4)',
      }}
    >
      <div
        style={{
          position: 'absolute',
          inset: 0,
          background: `radial-gradient(ellipse 55% 80% at 12% 50%,${color}12,transparent)`,
          pointerEvents: 'none',
        }}
      />
      <div
        className="sp-head-inner"
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          position: 'relative',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
          <div
            style={{
              width: 56,
              height: 56,
              borderRadius: r(16),
              background: `${color}18`,
              border: `1.5px solid ${color}30`,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '1.9rem',
              flexShrink: 0,
            }}
          >
            {emoji}
          </div>
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 4 }}>
              <h1 style={{ fontSize: '1.55rem', fontWeight: 800, color: 'var(--foreground)', margin: 0 }}>
                {displayTitle}
              </h1>
            </div>
            {displaySub && (
              <p style={{ fontSize: '0.78rem', color: 'rgba(255,255,255,0.46)', margin: 0 }}>
                {displaySub}
              </p>
            )}
          </div>
        </div>
        {action && (
          <button
            onClick={action.onClick}
            className="sp-head-btn"
            style={{
              height: 44,
              padding: '0 22px',
              borderRadius: '99px',
              border: 'none',
              background: DS.gradC,
              color: 'var(--foreground)',
              fontWeight: 700,
              fontSize: '0.875rem',
              boxShadow: `0 4px 16px ${DS.cyan}30`,
              cursor: 'pointer',
              flexShrink: 0,
            }}
          >
            {displayLabel}
          </button>
        )}
      </div>
    </div>
  );
}

